package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	word := strings.TrimSpace(scanner.Text())
	scanner.Scan()
	count, err := strconv.Atoi(strings.TrimSpace(scanner.Text()))
	if err != nil {
		fmt.Println(err)
		return
	}
	words := make([]string, count)
	for i := range words {
		words[i] = word
	}
	fmt.Println(strings.Join(words, " "))
}

