package main

import (
	"fmt"
	"sort"
)

func main() {
	tags := make(map[string]struct{})
	for {
		var tag string
		if _, err := fmt.Scan(&tag); err != nil {
			break
		}
		tags[tag] = struct{}{}
	}
	sorted := make([]string, 0, len(tags))
	for t := range tags {
		sorted = append(sorted, t)
	}
	sort.Strings(sorted)
	for _, t := range sorted {
		fmt.Println(t)
	}
	fmt.Println("Total:", len(tags))
}

steps.body:
For line-based records, make a scanner with `scanner := bufio.NewScanner(os.Stdin)` and loop with `for scanner.Scan() { }`. It runs once per line and stops when the input ends. Split each line with `strings.Fields`, which ignores extra spaces and returns an empty slice for a blank line, then convert the parts with `strconv`. This loop fills `students`, a `[]Student` where `Student` is a struct with `Name` and `Score` fields.

```go harness
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Student struct {
	Name  string
	Score int
}

func main() {
	var students []Student
	scanner := bufio.NewScanner(os.Stdin)
	{{code}}
	fmt.Println(students)
}
```

```stdin
Ana 95
Ben 58

Cleo 72
```

```go
for scanner.Scan() {
	fields := strings.Fields(scanner.Text())
	if len(fields) != 2 {
		continue // blank or malformed line
	}
	score, err := strconv.Atoi(fields[1])
	if err != nil {
		fmt.Println(err)
		return
	}
	students = append(students, Student{Name: fields[0], Score: score})
}
```

Checking `len(fields)` first prevents an index out of range panic on a short line. Each record goes into a `[]Student` with `append`, which copies the struct into the slice's backing array. After the loop, check `scanner.Err()`. It is `nil` when the input simply ended, and an error when reading failed, such as on a line longer than 64 KB.

Once the data is in structs, the rest is what you already know: call methods on each record and sort with `sort.Slice`. Give the sort a tie-breaker, such as the name, so equal keys always print in the same order.

example.code:
package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Student struct {
	Name  string
	Score int
}

func (s Student) Passed() bool { return s.Score >= 60 }

func main() {
	var students []Student
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) != 2 {
			continue // skip blank or malformed lines
		}
		score, err := strconv.Atoi(fields[1])
		if err != nil {
			fmt.Println(err)
			return
		}
		students = append(students, Student{Name: fields[0], Score: score})
	}
	if err := scanner.Err(); err != nil {
		fmt.Println(err)
		return
	}
	sort.Slice(students, func(i, j int) bool {
		if students[i].Score != students[j].Score {
			return students[i].Score > students[j].Score
		}
		return students[i].Name < students[j].Name
	})
	for i, s := range students {
		result := "fail"
		if s.Passed() {
			result = "pass"
		}
		fmt.Printf("%d. %s %d %s\n", i+1, s.Name, s.Score, result)
	}
}

