package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Line struct {
	Item  string
	Qty   int
	Price float64
}

func (l Line) Total() float64 { return float64(l.Qty) * l.Price }

func main() {
	var lines []Line
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) != 3 {
			continue
		}
		qty, err := strconv.Atoi(fields[1])
		if err != nil {
			fmt.Println(err)
			return
		}
		price, err := strconv.ParseFloat(fields[2], 64)
		if err != nil {
			fmt.Println(err)
			return
		}
		lines = append(lines, Line{Item: fields[0], Qty: qty, Price: price})
	}
	if err := scanner.Err(); err != nil {
		fmt.Println(err)
		return
	}
	sort.Slice(lines, func(i, j int) bool {
		if lines[i].Total() != lines[j].Total() {
			return lines[i].Total() > lines[j].Total()
		}
		return lines[i].Item < lines[j].Item
	})
	grand := 0.0
	for _, l := range lines {
		fmt.Printf("%s %.2f\n", l.Item, l.Total())
		grand += l.Total()
	}
	fmt.Printf("Grand total: %.2f\n", grand)
}
